const dialog=document.querySelector('dialog');document.querySelectorAll('[data-dialog]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#dialog-title').textContent=button.dataset.dialog;dialog.querySelector('form').reset();dialog.querySelector('.form-note').textContent='Interactive design preview. No data is sent.';dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});document.querySelector('form').addEventListener('submit',event=>{event.preventDefault();dialog.querySelector('.form-note').textContent='Thank you! This is a design preview — your email has not been submitted.'});document.querySelector('.menu').addEventListener('click',()=>{const nav=document.querySelector('nav');nav.classList.toggle('open');document.querySelector('.menu').setAttribute('aria-expanded',nav.classList.contains('open'))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('nav').classList.remove('open')));
